INSERT OR IGNORE INTO guides (id, machine, problem, yaml, status) VALUES ('dtf-banding', '["dtf"]', 'Lines or banding in prints', 'id: dtf-banding
machine: dtf
problem: Lines or banding in prints
safety: "Keep hands away from the moving print head."
steps:
  - text: "Print a nozzle check. If lines are missing, follow the head clogging fix first."
  - text: "Check the film is lying flat and is not touching the print head."
  - text: "In your RIP software, check the print mode / pass setting. Try a higher-quality mode (more passes)."
  - text: "Print a small test again and compare."
  - text: "Look at the encoder strip (the clear plastic strip behind the head). Is there ink or dust on it?"
  - text: "If it is dirty: switch the printer OFF and unplug it. Lightly dampen a lint-free cloth with distilled water. No chemicals."
  - text: "Gently wipe the strip from one end to the other. Do not bend, pull or remove it. Let it dry fully, then switch the printer on and print a test."
max_attempts_before_escalation: 2
escalate_if:
  - "Banding stays after a perfect nozzle check"
  - "The encoder strip is scratched, bent or damaged"
  - "Banding stays after cleaning the encoder strip"
  - "The head hits the film"
prevention_tip: "Keep the film flat and stored in a dry place. Print a nozzle check before big jobs."
status: draft
owner_check:
  - "Which pass/quality setting do you recommend for your DTF models?"
', 'draft');
INSERT OR IGNORE INTO guides (id, machine, problem, yaml, status) VALUES ('dtf-colours-wrong', '["dtf"]', 'Colours missing or wrong', 'id: dtf-colours-wrong
machine: dtf
problem: Colours missing or wrong
safety: "Wear gloves when handling ink."
steps:
  - text: "Print a nozzle check. Is every colour there (C, M, Y, K and White)?"
  - text: "If a colour is missing, follow the head clogging fix."
  - text: "Check each ink tank. Make sure no colour is empty and the right ink is in the right tank."
  - text: "In your RIP software, check that the correct colour profile (ICC) for your film and ink is selected."
  - text: "Print a small colour test again."
max_attempts_before_escalation: 2
escalate_if:
  - "Wrong ink was filled in a tank"
  - "Colours still wrong with a perfect nozzle check and the correct profile"
prevention_tip: "Label your ink tanks and refill one colour at a time."
status: draft
owner_check:
  - "Which ICC profile names do your customers use for DTF? Should the agent name them?"
', 'draft');
INSERT OR IGNORE INTO guides (id, machine, problem, yaml, status) VALUES ('dtf-film-feed', '["dtf"]', 'Film feed problems (film not moving, skewed or jamming)', 'id: dtf-film-feed
machine: dtf
problem: Film feed problems (film not moving, skewed or jamming)
safety: "Pause or stop the print before touching the film. Keep hands away from the moving head."
steps:
  - text: "Stop the print. Check the film roll is loaded straight and the coated side is facing up. Not sure which side? Scratch a corner gently with your fingernail — the coated side leaves a mark."
  - text: "Check the pinch rollers are pressed down on the film."
  - text: "Check the film is not touching or catching on anything along its path."
  - text: "If you have a take-up roller, check it is switched on and the film is attached straight."
  - text: "Do a short test print."
max_attempts_before_escalation: 2
escalate_if:
  - "The feed motor makes a grinding noise"
  - "The film keeps jamming after reloading"
  - "The head hits the film"
prevention_tip: "Store film rolls flat in their bag, away from humidity, and load them straight every time."
status: approved
owner_check: []
', 'approved');
INSERT OR IGNORE INTO guides (id, machine, problem, yaml, status) VALUES ('dtf-head-clog', '["dtf"]', 'Head clogging / missing nozzles', 'id: dtf-head-clog
machine: dtf
problem: Head clogging / missing nozzles
safety: "Keep the printer ON for cleaning. Wear gloves. Keep ink away from eyes and skin."
steps:
  - text: "Print a nozzle check from your printer software."
  - text: "Look at the nozzle check. Are any lines missing or broken? Send a photo if you can."
  - text: "Check the ink tanks. Make sure every colour has ink and no tube is empty or has big air bubbles."
  - text: "Run 1 normal head cleaning from the software. Wait 2 minutes, then print the nozzle check again. (Repeat up to 3 normal cleanings in total.)"
  - text: "Still missing? Clean the capping station and wiper. Use the software''s move-carriage option to move the head aside. Never push the head by hand."
  - text: "Wear gloves. Dip a clean foam swab in iNK Fusion cleaning solution or distilled water (battery top-up water — NEVER battery acid)."
  - text: "Gently wipe the rubber edge of the capping station and the wiper blade. Do not touch the bottom of the print head."
  - text: "Let the head go back to its home position (or use the software''s ''home'' option). Then print the nozzle check again."
  - text: "Run 1 power (strong) cleaning. Only do this once. Then print the nozzle check again."
max_attempts_before_escalation: 3
escalate_if:
  - "Still missing after the power/strong cleaning"
  - "No ink comes out after 3 cleanings"
  - "Ink is leaking from the head or tubes"
  - "A head error code is shown"
  - "The nozzle check is completely blank"
prevention_tip: "Print a nozzle check every morning. Keep the printer switched on, or print a small test daily so the ink keeps moving."
status: approved
owner_check: []
', 'approved');
INSERT OR IGNORE INTO guides (id, machine, problem, yaml, status) VALUES ('dtf-powder-not-sticking', '["dtf"]', 'Powder not sticking to the print', 'id: dtf-powder-not-sticking
machine: dtf
problem: Powder not sticking to the print
safety: "Wear a dust mask when handling powder. The dryer is hot — do not touch it."
steps:
  - text: "Check you are printing on the coated side of the film. Not sure which side? Scratch a corner gently with your fingernail — the coated side leaves a mark."
  - text: "Check the white layer is printing. Powder sticks to the wet white ink."
  - text: "Check the powder is dry and free-flowing. Damp powder forms lumps and does not stick well."
  - text: "Check the shaker spreads powder over the whole print, and the print is still wet when the powder lands."
  - text: "Print a small test and check again."
max_attempts_before_escalation: 2
escalate_if:
  - "The shaker is not working"
  - "Powder still does not stick with fresh powder and good white"
prevention_tip: "Keep powder in a sealed container in a dry place. Close the bag after use."
status: draft
owner_check:
  - "Any other common causes you see with your powder (for example ink amount settings)?"
', 'draft');
INSERT OR IGNORE INTO guides (id, machine, problem, yaml, status) VALUES ('dtf-shaker-dryer', '["dtf"]', 'Powder shaker / dryer not heating or not working', 'id: dtf-shaker-dryer
machine: dtf
problem: Powder shaker / dryer not heating or not working
safety: "The dryer is very hot. Do not touch the heating area. Never open the electrical box — call us instead."
steps:
  - text: "Check the shaker/dryer is plugged in and the power switch is ON."
  - text: "Check the dryer temperature setting on the control panel. iNK Fusion recommends 120°C."
  - text: "Wait 10 minutes. Does the dryer warm up?"
  - text: "Check the film is fed straight into the shaker and is not stuck."
max_attempts_before_escalation: 1
escalate_if:
  - "No power at all"
  - "Not heating after 10 minutes"
  - "Burning smell, smoke or sparks — switch off and unplug straight away"
  - "Belt or motor not moving"
prevention_tip: "Clean loose powder from the shaker every day and keep the area dry."
status: approved
owner_check: []
', 'approved');
INSERT OR IGNORE INTO guides (id, machine, problem, yaml, status) VALUES ('dtf-transfer-peeling', '["dtf"]', 'Transfer peeling or cracking after pressing', 'id: dtf-transfer-peeling
machine: dtf
problem: Transfer peeling or cracking after pressing
ask_first:
  - "What fabric are you pressing on?"
  - "Is your film hot-peel or cold-peel?"
safety: "The heat press is hot. Keep hands clear of the plates."
steps:
  - text: "Check the powder was fully cured in the dryer at 120°C. It should look smooth and glossy, not powdery."
  - text: "Pre-press the garment for a few seconds to remove moisture."
  - text: "Check your heat press settings. iNK Fusion recommends 160°C for 10 seconds for DTF transfers."
  - text: "Peel the film the right way: hot-peel films right away, cold-peel films only after cooling completely."
  - text: "Press again with a cover sheet for a few seconds after peeling."
max_attempts_before_escalation: 2
escalate_if:
  - "The heat press temperature seems wrong (see the heat press guides)"
  - "Peeling continues with correct settings"
prevention_tip: "Always pre-press the garment, and follow the film''s hot-peel or cold-peel instruction."
status: approved
owner_check: []
', 'approved');
INSERT OR IGNORE INTO guides (id, machine, problem, yaml, status) VALUES ('dtf-white-ink-clog', '["dtf"]', 'White ink clogging / weak or missing white layer', 'id: dtf-white-ink-clog
machine: dtf
problem: White ink clogging / weak or missing white layer
safety: "Keep the printer ON. Wear gloves. Do not open the ink lines or the head."
steps:
  - text: "Check that white ink circulation is ON: look at the white ink tube — the ink should be moving — or listen for a soft pump sound."
  - text: "Before refilling, shake the white ink bottle well. White ink settles quickly."
  - text: "Print a nozzle check and look at the white channel. Send a photo if you can."
  - text: "Run 1 normal head cleaning for the white channel, then print the nozzle check again. (Repeat up to 3 normal cleanings in total.)"
  - text: "Still missing? Clean the capping station and wiper. Use the software''s move-carriage option to move the head aside. Never push the head by hand."
  - text: "Wear gloves. Dip a clean foam swab in iNK Fusion cleaning solution or distilled water (battery top-up water — NEVER battery acid)."
  - text: "Gently wipe the rubber edge of the capping station and the wiper blade. Do not touch the bottom of the print head."
  - text: "Let the head go back to its home position (or use the software''s ''home'' option). Then print the nozzle check again."
  - text: "Run 1 power (strong) cleaning. Only do this once. Then print the nozzle check again."
max_attempts_before_escalation: 3
escalate_if:
  - "Still missing after the power/strong cleaning"
  - "White still missing after 3 cleanings"
  - "The white circulation pump is not running or makes a noise"
  - "Ink is leaking"
  - "A head error code is shown"
prevention_tip: "Shake the white ink bottle before every refill, and keep white circulation switched on, even when the printer is not in use."
status: approved
owner_check: []
', 'approved');
INSERT OR IGNORE INTO guides (id, machine, problem, yaml, status) VALUES ('epson-banding', '["epson"]', 'Lines or banding in prints', 'id: epson-banding
machine: epson
problem: Lines or banding in prints
safety: "Keep hands out of the printer while it is printing."
steps:
  - text: "Print a nozzle check. If lines are missing, follow the head clogging fix first."
  - text: "Run Print Head Alignment (Maintenance > Print Head Alignment)."
  - text: "Check the paper type in the print settings matches the paper you are using."
  - text: "Try printing in a higher quality setting."
max_attempts_before_escalation: 2
escalate_if:
  - "Banding stays after a perfect nozzle check and alignment"
prevention_tip: "Use the correct paper type setting and keep paper dry and flat."
status: draft
owner_check: []
', 'draft');
INSERT OR IGNORE INTO guides (id, machine, problem, yaml, status) VALUES ('epson-colours-wrong', '["epson"]', 'Colours missing or wrong', 'id: epson-colours-wrong
machine: epson
problem: Colours missing or wrong
ask_first:
  - "Is your printer used for sublimation?"
safety: "Wear gloves when handling ink."
steps:
  - text: "Print a nozzle check. Is every colour there?"
  - text: "If a colour is missing, follow the head clogging fix."
  - text: "Check each tank is filled with the right colour."
  - text: "For sublimation: colours on paper look dull — that is normal. Check the colour after pressing."
  - text: "For sublimation: check the correct ICC profile is selected in your print software."
max_attempts_before_escalation: 2
escalate_if:
  - "Wrong ink filled in a tank"
  - "Colours still wrong after pressing with the correct profile"
prevention_tip: "Refill one colour at a time and check the bottle colour matches the tank."
status: draft
owner_check:
  - "Which ICC profile do you supply for sublimation-converted Epsons?"
', 'draft');
INSERT OR IGNORE INTO guides (id, machine, problem, yaml, status) VALUES ('epson-error-lights', '["epson"]', 'Error lights and messages', 'id: epson-error-lights
machine: epson
problem: Error lights and messages
ask_first:
  - "Which lights are on or blinking? Or what does the screen/PC message say? A photo helps."
safety: "Do not open the printer cover screws or reset the printer with unofficial software."
steps:
  - text: "Paper light blinking: reload the paper and press the paper button."
  - text: "Ink light on: check that every ink tank has ink, and refill if needed."
  - text: "Switch the printer off, wait 30 seconds, and switch it on again."
  - text: "Did the light go off?"
max_attempts_before_escalation: 1
escalate_if:
  - "All lights blinking together"
  - "Message: ''parts inside your printer are at the end of their service life'' or ''ink pad'' (waste ink pad full)"
  - "Any error that stays after restarting"
prevention_tip: "Avoid extra head cleanings — each one fills the waste ink pad."
status: draft
owner_check:
  - "Do you reset waste ink pad counters for customers as a paid service? (The agent will never tell customers to do it themselves.)"
', 'draft');
INSERT OR IGNORE INTO guides (id, machine, problem, yaml, status) VALUES ('epson-head-clog', '["epson"]', 'Head clogging / missing nozzles', 'id: epson-head-clog
machine: epson
problem: Head clogging / missing nozzles
ask_first:
  - "Which Epson model do you have? (for example L805, L1800)"
  - "Is it used with normal ink or sublimation ink?"
safety: "Keep the printer ON. Wear gloves when handling ink."
steps:
  - text: "Print a nozzle check (Epson printer settings > Maintenance > Nozzle Check)."
  - text: "Look at the pattern. Are any lines missing? Send a photo if you can."
  - text: "Check all ink tanks have ink above the lower line."
  - text: "Run 1 Head Cleaning. Wait 5 minutes, then print the nozzle check again. (Repeat up to 3 normal cleanings in total.)"
  - text: "Still missing? If your model has Power Cleaning, run it once only. Then print the nozzle check again."
max_attempts_before_escalation: 3
escalate_if:
  - "Still missing after the power/strong cleaning"
  - "Still missing after 3 cleanings"
  - "Message about ''ink pad'' or ''parts at end of service life''"
  - "Ink leaking inside the printer"
prevention_tip: "Print at least one page or a nozzle check every 2–3 days. Sublimation ink dries faster, so print daily."
status: approved
owner_check: []
', 'approved');
INSERT OR IGNORE INTO guides (id, machine, problem, yaml, status) VALUES ('epson-paper-feed', '["epson"]', 'Paper feed problems (not feeding, jamming, skewed)', 'id: epson-paper-feed
machine: epson
problem: Paper feed problems (not feeding, jamming, skewed)
safety: "Switch the printer off before removing jammed paper. Pull paper out gently. Never force it."
steps:
  - text: "If paper is jammed, switch off the printer and gently pull the paper out in the direction it feeds."
  - text: "Fan the paper stack and load fewer sheets (about 20)."
  - text: "Slide the edge guides so they touch the paper lightly."
  - text: "Check the paper is not curled, damp or too thick for the printer."
  - text: "Switch on and print a test page."
max_attempts_before_escalation: 2
escalate_if:
  - "Paper torn and stuck inside"
  - "Grinding noise"
  - "Paper never picks up"
prevention_tip: "Keep paper in its pack in a dry place, and don''t overfill the tray."
status: draft
owner_check: []
', 'draft');
INSERT OR IGNORE INTO guides (id, machine, problem, yaml, status) VALUES ('heatpress-not-heating', '["heatpress"]', 'Not heating, or heating slowly', 'id: heatpress-not-heating
machine: heatpress
problem: Not heating, or heating slowly
safety: "Always unplug before touching the fuse. The plate may be hot even if the display is off. Never open the control box or touch wiring — call us instead."
steps:
  - text: "Check the plug is firmly in the socket and the power switch is ON."
  - text: "Test the wall socket with another device, like a phone charger."
  - text: "Check the temperature is set higher than the room temperature, and the display is on."
  - text: "Wait 10 minutes. Is the temperature rising on the display?"
  - text: "No power at all? Switch off and UNPLUG the press. If it has a fuse holder on the OUTSIDE (back or side), open it and look at the fuse."
  - text: "If the fuse wire is broken or black, replace it with a new fuse of the SAME rating (written on the fuse). Plug in and switch on again."
max_attempts_before_escalation: 1
escalate_if:
  - "No power after checking the socket and outside fuse"
  - "The new fuse blows again — do not try another fuse"
  - "No outside fuse holder — never open the control box"
  - "Display on but temperature not rising"
  - "Burning smell, smoke or sparks — switch off and unplug straight away"
  - "Not at the set temperature after 50 minutes (normal is about 40 minutes to reach 180°C)"
prevention_tip: "Plug the heat press straight into a wall socket. Do not use a thin extension cord or a multi-plug."
status: approved
owner_check: []
', 'approved');
INSERT OR IGNORE INTO guides (id, machine, problem, yaml, status) VALUES ('heatpress-temp-mismatch', '["heatpress"]', 'Temperature not matching the setting', 'id: heatpress-temp-mismatch
machine: heatpress
problem: Temperature not matching the setting
safety: "The plate is hot. Do not touch it. Use a heat-safe thermometer only."
steps:
  - text: "Let the press reach the set temperature and wait 5 more minutes."
  - text: "If you have a surface or infrared thermometer, measure the centre of the plate."
  - text: "Measure the 4 corners too. Write down all the readings."
  - text: "Send us the readings and the temperature setting. If the difference is more than 15°C, our technician can check and calibrate your press."
max_attempts_before_escalation: 1
escalate_if:
  - "Difference of more than 15°C from the setting"
  - "Corners much colder than the centre"
  - "Temperature keeps rising past the setting"
prevention_tip: "Check the plate temperature with a thermometer once a month."
status: approved
owner_check: []
', 'approved');
INSERT OR IGNORE INTO guides (id, machine, problem, yaml, status) VALUES ('heatpress-timer-alarm', '["heatpress"]', 'Timer or alarm not working', 'id: heatpress-timer-alarm
machine: heatpress
problem: Timer or alarm not working
ask_first:
  - "Does your press timer start by itself when you close it, or do you press a start button?"
safety: "The plate is hot. Do not open the control box."
steps:
  - text: "Check the time setting on the controller is not 0."
  - text: "Switch the press off, wait 1 minute, and switch it on again."
  - text: "Set a short time, like 10 seconds, and close the press. If your model has a start button, press it. Does the timer start counting?"
max_attempts_before_escalation: 1
escalate_if:
  - "Timer does not start when the press is closed"
  - "No alarm sound"
  - "Controller buttons don''t respond"
prevention_tip: "Keep the controller dry and away from steam."
status: approved
owner_check: []
', 'approved');
INSERT OR IGNORE INTO guides (id, machine, problem, yaml, status) VALUES ('heatpress-transfer-not-sticking', '["heatpress"]', 'Transfer not sticking or fading', 'id: heatpress-transfer-not-sticking
machine: heatpress
problem: Transfer not sticking or fading
ask_first:
  - "What are you pressing? (DTF, sublimation, vinyl) And onto what item?"
  - "What temperature, time and pressure are you using?"
safety: "The plate is hot. Keep hands clear."
steps:
  - text: "Check the press really reaches the set temperature (see the temperature guide if not sure)."
  - text: "Check your settings. iNK Fusion recommends: DTF 160°C for 10 seconds; sublimation on fabric 210°C for 45 seconds. For mugs, caps or other items, please contact iNK Fusion for settings."
  - text: "Pre-press the item for a few seconds to remove moisture."
  - text: "Sublimation: check the item is polyester or polymer-coated."
  - text: "Press a test piece and check again."
max_attempts_before_escalation: 2
escalate_if:
  - "The press temperature is wrong"
  - "Still not sticking with correct settings"
prevention_tip: "Keep a written list of the settings that work for each item and transfer type."
status: approved
owner_check: []
', 'approved');
INSERT OR IGNORE INTO guides (id, machine, problem, yaml, status) VALUES ('heatpress-uneven-pressure', '["heatpress"]', 'Uneven pressure or uneven transfer', 'id: heatpress-uneven-pressure
machine: heatpress
problem: Uneven pressure or uneven transfer
safety: "The plate is hot. Keep hands clear when closing the press."
steps:
  - text: "Check the item is flat and centred under the plate. Remove seams, buttons or zips from under the transfer area."
  - text: "Use a heat press pillow or pad if the item has seams."
  - text: "Adjust the pressure knob to your normal setting."
  - text: "Do a paper test: press a sheet of paper and check the scorch mark is even."
max_attempts_before_escalation: 2
escalate_if:
  - "The plate is bent or loose"
  - "Pressure knob does not change pressure"
  - "Paper test still very uneven"
prevention_tip: "Always centre the item and use the same pressure setting for the same job."
status: approved
owner_check: []
', 'approved');
INSERT OR IGNORE INTO guides (id, machine, problem, yaml, status) VALUES ('pc-printer-not-detected', '["dtf","epson","sublimation"]', 'Printer not detected by the PC (USB / network)', 'id: pc-printer-not-detected
machine: [dtf, epson, sublimation]
problem: Printer not detected by the PC (USB / network)
ask_first:
  - "Is the printer connected by USB or network cable?"
safety: "Switch the printer off before unplugging or plugging in cables."
steps:
  - text: "Check the printer is on and the cable is plugged in at both ends."
  - text: "USB: try a different USB port directly on the computer. Avoid USB hubs."
  - text: "USB: try a different USB cable if you have one."
  - text: "Network: check the network cable lights are blinking at the printer and the router/PC."
  - text: "Restart the printer, then restart the computer."
max_attempts_before_escalation: 1
escalate_if:
  - "Still not detected with another cable and port"
  - "The network IP settings need to be changed"
prevention_tip: "Use a good-quality, short USB cable and keep it out of the way so it doesn''t get pulled."
status: draft
owner_check:
  - "Should the agent help customers check the printer''s IP address, or leave network setup to technicians?"
', 'draft');
INSERT OR IGNORE INTO guides (id, machine, problem, yaml, status) VALUES ('software-dongle-not-detected', '["dtf","epson","sublimation"]', 'Licence / dongle not detected', 'id: software-dongle-not-detected
machine: [dtf, epson, sublimation]
problem: Licence / dongle not detected
ask_first:
  - "Which software do you use? (Maintop, PrintExp, RIIN, Wasatch SoftRIP, SAi Flexi)"
safety: "Do not try to copy, reset or ''crack'' the licence. This can permanently disable it."
steps:
  - text: "Unplug the dongle and plug it into a different USB port directly on the computer (not a USB hub)."
  - text: "Check that the light on the dongle turns on, if it has one."
  - text: "Restart the computer with the dongle plugged in."
  - text: "Open the software again."
max_attempts_before_escalation: 1
escalate_if:
  - "The dongle light does not turn on"
  - "Still not detected after restarting"
  - "The dongle is lost or damaged"
prevention_tip: "Keep the dongle plugged directly into the computer and do not remove it while the software is open."
status: draft
owner_check:
  - "Should customers reinstall the dongle driver (for example Sentinel/HASP) themselves? If yes, which driver for each software?"
', 'draft');
INSERT OR IGNORE INTO guides (id, machine, problem, yaml, status) VALUES ('software-printer-not-found', '["dtf","epson","sublimation"]', 'RIP software can''t find the printer', 'id: software-printer-not-found
machine: [dtf, epson, sublimation]
problem: RIP software can''t find the printer
ask_first:
  - "Which software do you use?"
  - "Is the printer connected by USB or network cable?"
safety: "Switch the printer off before unplugging or plugging in cables."
steps:
  - text: "Check the printer is switched on and shows no error."
  - text: "Check the USB or network cable is firmly plugged in at both ends."
  - text: "In the software, check the correct printer and port are selected."
  - text: "Close the software, restart the printer, then restart the computer. Open the software again."
max_attempts_before_escalation: 1
escalate_if:
  - "Still not found after restarting"
  - "The printer shows an error"
prevention_tip: "Use the same USB port every time and avoid long or cheap USB cables."
status: draft
owner_check:
  - "Where is the printer/port setting in each software? The agent can name the menu if you add it."
', 'draft');
INSERT OR IGNORE INTO guides (id, machine, problem, yaml, status) VALUES ('software-rip-wont-open', '["dtf","epson","sublimation"]', 'RIP or print software won''t open', 'id: software-rip-wont-open
machine: [dtf, epson, sublimation]
problem: RIP or print software won''t open
ask_first:
  - "Which software do you use? (Maintop, PrintExp, RIIN, Wasatch SoftRIP, SAi Flexi)"
  - "Do you see an error message? Please send a photo of the screen."
safety: "Do not uninstall the software or delete licence files — this can lose your licence."
steps:
  - text: "Close the software fully. Then restart the computer."
  - text: "Make sure the licence dongle (USB key) is plugged in, if your software uses one."
  - text: "Right-click the software icon and choose ''Run as administrator''."
  - text: "Check that antivirus software has not blocked or removed the program. If it has, please tell us — do not change antivirus settings unless you know how."
max_attempts_before_escalation: 1
escalate_if:
  - "Licence or activation error"
  - "Software was removed or files are missing"
  - "Error message stays after restarting"
prevention_tip: "Do not install Windows updates in the middle of a print job, and keep a note of your licence details in a safe place."
status: draft
owner_check:
  - "Any software-specific tips for Maintop, PrintExp, RIIN, Wasatch or Flexi that customers can safely do?"
', 'draft');
INSERT OR IGNORE INTO guides (id, machine, problem, yaml, status) VALUES ('sublimation-banding', '["sublimation"]', 'Lines or banding in prints (large-format)', 'id: sublimation-banding
machine: sublimation
problem: Lines or banding in prints (large-format)
safety: "Keep hands away from the moving head and the paper path."
steps:
  - text: "Print a nozzle check. If lines are missing, follow the head clogging fix first."
  - text: "Check the paper is flat and the take-up roller is working."
  - text: "Run the paper feed calibration (step calibration) from the panel or software."
  - text: "Check your RIP print mode. Try a higher pass / quality setting."
  - text: "Print a small test and compare."
max_attempts_before_escalation: 2
escalate_if:
  - "Banding stays after nozzle check and calibration"
  - "Head hitting the paper"
  - "Encoder strip is dirty"
prevention_tip: "Run step calibration whenever you change paper type."
status: draft
owner_check:
  - "What is the menu name for step / feed calibration on your large-format models?"
', 'draft');
INSERT OR IGNORE INTO guides (id, machine, problem, yaml, status) VALUES ('sublimation-colours-wrong', '["sublimation"]', 'Colours missing or wrong after pressing', 'id: sublimation-colours-wrong
machine: sublimation
problem: Colours missing or wrong after pressing
ask_first:
  - "Which RIP software do you use?"
  - "What material are you pressing onto?"
safety: "The heat press is hot. Wear gloves when handling ink."
steps:
  - text: "Print a nozzle check. Is every colour there?"
  - text: "In your RIP, check the correct ICC profile for your ink and paper is selected."
  - text: "Check you are printing on the right side of the sublimation paper."
  - text: "Check the material is polyester or polymer-coated. Cotton will not hold sublimation colours."
  - text: "Check your heat press settings. For fabric, iNK Fusion recommends 210°C for 45 seconds. For mugs or other items, please contact iNK Fusion. If colours are pale, also see the heat press temperature guide."
max_attempts_before_escalation: 2
escalate_if:
  - "Colours still wrong with the correct profile, paper and settings"
prevention_tip: "Keep the same ICC profile, paper and press settings for repeat jobs."
status: approved
owner_check: []
', 'approved');
INSERT OR IGNORE INTO guides (id, machine, problem, yaml, status) VALUES ('sublimation-error-codes', '["sublimation"]', 'Error lights and codes (large-format)', 'id: sublimation-error-codes
machine: sublimation
problem: Error lights and codes (large-format)
ask_first:
  - "What error code or message is on the panel or PC? Please send a photo."
safety: "Do not open covers or the electronics. Switch off before clearing any paper jam."
steps:
  - text: "Write down or photograph the error code."
  - text: "Check the paper is loaded and there is no jam."
  - text: "Switch the printer off, wait 30 seconds, and switch it on again."
  - text: "Does the error come back?"
max_attempts_before_escalation: 1
escalate_if:
  - "The error comes back after restarting"
  - "Any head, voltage or mainboard error"
prevention_tip: "Note down error codes when they appear — it helps our technicians fix the problem faster."
status: draft
owner_check:
  - "Please share the error code sheets for your large-format models so the agent can explain common codes."
', 'draft');
INSERT OR IGNORE INTO guides (id, machine, problem, yaml, status) VALUES ('sublimation-head-clog', '["sublimation"]', 'Head clogging / missing nozzles (large-format)', 'id: sublimation-head-clog
machine: sublimation
problem: Head clogging / missing nozzles (large-format)
ask_first:
  - "Which RIP or print software do you use?"
safety: "Keep the printer ON. Wear gloves. Keep hands away from the moving head."
steps:
  - text: "Print a nozzle check (test print) from the printer panel or the software."
  - text: "Look at the pattern. Are any lines missing? Send a photo if you can."
  - text: "Check the ink tanks are full and the ink tubes have no big air gaps."
  - text: "Run 1 normal cleaning, then print the nozzle check again. (Repeat up to 3 normal cleanings in total.)"
  - text: "Still missing? Clean the capping station and wiper. Use the panel''s move-carriage option to move the head aside. Never push the head by hand."
  - text: "Wear gloves. Dip a clean foam swab in iNK Fusion cleaning solution or distilled water (battery top-up water — NEVER battery acid)."
  - text: "Gently wipe the rubber edge of the capping station and the wiper blade. Do not touch the bottom of the print head."
  - text: "Let the head go back to its home position (or use the software''s ''home'' option). Then print the nozzle check again."
  - text: "Run 1 power (strong) cleaning. Only do this once. Then print the nozzle check again."
max_attempts_before_escalation: 3
escalate_if:
  - "Still missing after the power/strong cleaning"
  - "Still missing after 3 cleanings"
  - "Ink leaking"
  - "Head error code on the panel"
  - "Ink not reaching the head (empty tubes or dampers)"
prevention_tip: "Print a nozzle check every morning and do not leave the printer switched off for days."
status: approved
owner_check: []
', 'approved');
INSERT OR IGNORE INTO guides (id, machine, problem, yaml, status) VALUES ('sublimation-paper-feed', '["sublimation"]', 'Paper feed problems (skewing, wrinkling, not feeding)', 'id: sublimation-paper-feed
machine: sublimation
problem: Paper feed problems (skewing, wrinkling, not feeding)
safety: "Pause the print before touching the paper. Keep hands away from the moving head."
steps:
  - text: "Stop the print. Check the paper roll is loaded straight and both ends are even."
  - text: "Check all pinch rollers are down on the paper."
  - text: "Check the take-up roller is on and the paper is taped straight."
  - text: "Check the paper is not damp (damp paper wrinkles)."
  - text: "Do a short test print."
max_attempts_before_escalation: 2
escalate_if:
  - "Feed motor noise or the paper does not move at all"
  - "Paper keeps skewing after reloading"
prevention_tip: "Store paper rolls in their bag in a dry place."
status: draft
owner_check: []
', 'draft');
